            P('Nell’apprendimento **non supervisionato** invece le etichette non ci sono: il modello cerca strutture da solo, come gruppi di clienti simili (clustering).', 'In **unsupervised** learning there are no labels: the model looks for structure by itself, such as groups of similar customers (clustering).'),
        ], [
            Q('s1', L('Prevedere il prezzo di una casa è…', 'Predicting a house price is…'), [L('Regressione', 'Regression'), L('Classificazione', 'Classification'), L('Clustering', 'Clustering'), L('Compressione', 'Compression')], 0, L('L’etichetta è un numero.', 'The label is a number.')),
            Q('s2', L('Che cosa contiene `y`?', 'What does `y` contain?'), [L('L’etichetta, la risposta giusta', 'The label, the right answer'), L('Le caratteristiche', 'The features'), L('Il modello', 'The model'), L('Gli errori', 'The errors')], 0, L('`X` sono gli input.', '`X` are the inputs.')),
            Q('s3', L('Raggruppare clienti senza etichette è…', 'Grouping customers without labels is…'), [L('Non supervisionato', 'Unsupervised'), L('Supervisionato', 'Supervised'), L('Regressione', 'Regression'), L('Inferenza', 'Inference')], 0, L('Nessuna risposta giusta data.', 'No right answer given.')),
        ], task('python', L('Dal DataFrame `df` metti in `X` le colonne `eta` e `reddito`, e in `y` la colonna `acquista`.', 'From the DataFrame `df` put the columns `eta` and `reddito` in `X`, and the column `acquista` in `y`.'), "import pandas as pd\ndf = pd.read_csv(\"clienti.csv\")", [re('X\s*=\s*df\s*\[\s*\[\s*["\']eta["\']\s*,\s*["\']reddito["\']\s*\]\s*\]', L('Le caratteristiche in X', 'Features in X')), re('y\s*=\s*df\s*\[\s*["\']acquista["\']\s*\]', L('L’etichetta in y', 'The label in y'))], '', "X = df[[\"eta\", \"reddito\"]]\ny = df[\"acquista\"]"), [
            dMatch(pMatch(), [['X', L('Caratteristiche (input)', 'Features (inputs)')], ['y', L('Etichetta (risposta)', 'Label (answer)')], [L('Regressione', 'Regression'), L('Prevede un numero', 'Predicts a number')], [L('Classificazione', 'Classification'), L('Prevede una categoria', 'Predicts a category')], ['Clustering', L('Gruppi senza etichette', 'Groups without labels')]], L('Il vocabolario del ML.', 'ML vocabulary.')),
            dFlash(pFlash(), [[L('Riconoscere lo spam è classificazione', 'Spam detection is classification'), true], [L('Prevedere la temperatura di domani è classificazione', 'Predicting tomorrow’s temperature is classification'), false], [L('Il clustering usa le etichette', 'Clustering uses labels'), false], [L('Nel supervisionato ogni esempio ha la risposta', 'In supervised learning each example has the answer'), true]], L('Numero o categoria?', 'Number or category?')),
        ]),
        lesson('split', L('Dati di addestramento e di test', 'Training and test data'), [
            P('Se valuti un modello sugli stessi dati con cui ha imparato, il voto è falsato: potrebbe averli imparati a memoria. Si dividono i dati con `train_test_split`: di solito l’80% per addestrare e il 20% per il test.', 'If you evaluate a model on the same data it learned from, the score is inflated: it may have memorised them. You split the data with `train_test_split`: usually 80% to train and 20% to test.'),
            C('from sklearn.model_selection import train_test_split

